from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

OUT='تقرير-نظام-إدارة-البرامج-التدريبية.docx'
doc=Document(); sec=doc.sections[0]
sec.top_margin=Inches(.7); sec.bottom_margin=Inches(.7); sec.right_margin=Inches(.8); sec.left_margin=Inches(.8)
for s in ['Normal','Title','Heading 1','Heading 2']:
 st=doc.styles[s]; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:cs'),'Arial')
doc.styles['Normal'].font.size=Pt(12); doc.styles['Normal'].paragraph_format.line_spacing=1.35
doc.styles['Heading 1'].font.size=Pt(18); doc.styles['Heading 1'].font.color.rgb=RGBColor(23,54,93)
doc.styles['Heading 2'].font.size=Pt(14); doc.styles['Heading 2'].font.color.rgb=RGBColor(47,85,151)

def rtl(p,center=False):
 p.alignment=WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.RIGHT
 b=OxmlElement('w:bidi'); b.set(qn('w:val'),'1'); p._p.get_or_add_pPr().append(b)
 return p

def title(t,size=24):
 p=rtl(doc.add_paragraph(),True); r=p.add_run(t); r.bold=True; r.font.size=Pt(size); r.font.color.rgb=RGBColor(23,54,93)
def h1(t): rtl(doc.add_paragraph(t,style='Heading 1'))
def h2(t): rtl(doc.add_paragraph(t,style='Heading 2'))
def para(t): rtl(doc.add_paragraph(t))
def items(xs):
 for x in xs: para('• '+x)

# الغلاف
doc.add_paragraph('\n\n'); title('المجلس الأعلى للقضاء'); title('دائرة التدريب والتأهيل',16)
doc.add_paragraph('\n'); title('تقرير متكامل عن'); title('نظام إدارة البرامج التدريبية')
doc.add_paragraph('\n\n'); title('2026',15)
p=rtl(doc.add_paragraph('\n\n\n\nجميع الحقوق محفوظة للمجلس الأعلى للقضاء © 2026'),True)
doc.add_page_break()

sections=[
('1. الملخص التنفيذي', ['يُعد نظام إدارة البرامج التدريبية منصة إلكترونية متكاملة لتنظيم البرامج والدورات التدريبية التي تقدمها دائرة التدريب والتأهيل في المجلس الأعلى للقضاء. ويهدف إلى تحويل إجراءات إدارة البرامج والترشيحات من الأساليب اليدوية إلى إجراءات إلكترونية واضحة ومنظمة، ابتداءً من إنشاء البرنامج وتحديد دفعاته، مروراً باستقبال الترشيحات، وانتهاءً باعتماد المقبولين واستخراج التقارير.','يوفر النظام بيئة موحدة لمتابعة البرامج والدفعات والمرشحين، مع دعم البحث والفلترة والتصدير إلى Excel، ومتابعة المقاعد وحالات الطلبات والمؤشرات اللازمة لاتخاذ القرار.']),
('2. مقدمة',['تتطلب إدارة البرامج التدريبية التعامل مع أعداد كبيرة من البرامج والدفعات وطلبات الترشيح وبيانات الموظفين. وقد يؤدي الاعتماد على الملفات الورقية أو الجداول المنفصلة إلى تكرار البيانات وصعوبة البحث وتأخر المراجعة واحتمالية الخطأ.','جاء النظام ليقدم حلاً إلكترونياً مركزياً يسهّل إنشاء البرامج والدفعات وتحديد المواعيد والمقاعد واستقبال الطلبات ومراجعتها وفرزها وإعداد التقارير.']),
('3. أهداف النظام',['أتمتة إجراءات إدارة البرامج التدريبية.','توحيد بيانات البرامج والدفعات والترشيحات.','تسهيل تسجيل الموظفين وتسريع مراجعة الطلبات.','تنظيم المقاعد ومنع تجاوز العدد المطلوب لكل دفعة.','إبقاء التسجيل متاحاً لتكوين قائمة انتظار.','تسهيل البحث والفلترة حسب البرنامج والحالة.','تصدير البيانات والتقارير إلى Excel.','توفير مؤشرات إحصائية وتقليل الأخطاء والإجراءات الورقية.']),
('4. الفئات المستفيدة',['دائرة التدريب والتأهيل: إنشاء البرامج والدفعات ومراجعة الطلبات واستخراج التقارير.','مدير النظام: إدارة المستخدمين والصلاحيات والإعدادات ومتابعة التشغيل.','الموظفون والمرشحون: الاطلاع على البرامج وتقديم الترشيح إلكترونياً.','الإدارة العليا: الاستفادة من المؤشرات والإحصائيات والتقارير.']),
('5. المكونات الرئيسية',['الواجهة العامة لعرض البرامج والتفاصيل والدفعات والمقاعد والتسجيل.','لوحة التحكم لعرض مؤشرات البرامج والطلبات وحالاتها والتسجيلات الشهرية.','إدارة البرامج لإنشاء البرامج وتعديلها وإدارة حالتها.','إدارة الدفعات لتحديد المواعيد والعدد المطلوب ومتابعة المقبولين.','إدارة طلبات الترشيح للبحث والفلترة والقبول والرفض والتصدير.','التقارير والإحصائيات لاستخراج بيانات التسجيلات والبرامج والمقبولين.']),
('6. طريقة عمل النظام',['ينشئ المستخدم المخوّل البرنامج التدريبي ويحدد بياناته ووصفه وحالته.','تُضاف دفعة أو أكثر مع تحديد الاسم والتواريخ والعدد المطلوب.','يظهر البرنامج في الواجهة العامة ليطلع الموظف على التفاصيل والدفعات.','يعبئ الموظف بياناته ويختار البرنامج والدفعة ثم يُحفظ طلبه بحالة قيد المراجعة.','يبقى التسجيل متاحاً بعد اكتمال المقاعد لتكوين قائمة انتظار.','يراجع المسؤول الطلبات ويبحث بالاسم أو الرقم الوظيفي أو المسمى أو البريد أو الجهة.','يمكن فلترة المرشحين حسب البرنامج والحالة؛ فتظهر نتائج البرنامج المحدد فقط.','يتحقق النظام من السعة قبل قبول المرشح ويمنع تجاوز العدد المطلوب.','يمكن رفض الطلب أو تعديل حالته وفق الصلاحية.','يظهر عداد المقبولين مقابل العدد المطلوب لكل دفعة.']),
('7. البحث والفلترة',['البحث بالاسم والرقم الوظيفي والمسمى والبريد والدائرة أو المحكمة والقسم.','الفلترة حسب البرنامج التدريبي.','الفلترة حسب الحالة: قيد المراجعة أو مقبول أو مرفوض.','دمج نص البحث مع البرنامج والحالة ومسح الفلاتر عند الحاجة.']),
('8. تصدير ملفات Excel',['تصدير جميع طلبات الترشيح بصيغة .xlsx.','تصدير المقبولين للبرنامج المحدد فقط بعد التحقق من البرنامج.','تصدير تقرير التسجيلات وتقرير البرامج.','دعم العربية والاتجاه من اليمين إلى اليسار.','ترويسات منسقة وحدود وضبط تلقائي للأعمدة وتثبيت صف العناوين.','عرض التواريخ بالتقويم الميلادي.']),
('9. التقارير والمؤشرات',['إجمالي البرامج والبرامج النشطة والدفعات.','إجمالي التسجيلات والمقبولين والمرفوضين وقيد المراجعة.','التسجيلات خلال الأشهر الميلادية.','البرامج الأعلى إقبالاً وتوزيع التسجيلات حسب البرامج والدفعات.']),
('10. المستخدمون والصلاحيات',['يتيح النظام توزيع الصلاحيات لعرض لوحة التحكم وإدارة البرامج والدفعات ومراجعة الطلبات والقبول والرفض والتقارير والتصدير وإدارة المستخدمين والإعدادات. وتساعد الصلاحيات على حماية الوظائف الإدارية ومنع الوصول غير المصرح به.']),
('11. فوائد النظام',['توحيد الإجراءات والبيانات في منصة واحدة.','تسريع معالجة الطلبات وتحسين دقة البيانات.','ضبط المقاعد وتوفير قائمة انتظار.','توفير تقارير دقيقة تدعم اتخاذ القرار.','تقليل إدخال البيانات يدوياً واستخدام الورق.','تحسين تجربة الموظفين والمسؤولين.','تسهيل المتابعة اليومية والاستجابة لطلبات الإدارة.']),
('12. حماية البيانات والضوابط',['منح الصلاحيات حسب مسؤوليات المستخدم.','استخدام كلمات مرور قوية واتصال آمن.','الاحتفاظ بنسخ احتياطية دورية وحماية إعدادات الاتصال.','مراجعة صلاحيات المستخدمين بصورة دورية.','حماية ملفات Excel المصدرة وعدم إرسالها لجهات غير مخولة.','الالتزام بسياسات المجلس الخاصة بحماية البيانات.']),
('13. نقاط القوة',['واجهة عربية من اليمين إلى اليسار.','سهولة إدارة البرامج والدفعات والترشيحات.','استمرار التسجيل لقائمة الانتظار مع منع تجاوز المقبولين.','بحث متعدد الحقول وفلترة دقيقة حسب البرنامج والحالة.','تصدير Excel حقيقي وتقارير ميلادية.','مؤشرات واضحة للمقاعد وإدارة للصلاحيات.']),
('14. التحديات التي يعالجها النظام',['تشتت بيانات المرشحين وصعوبة الوصول إلى الطلبات.','تجاوز الطاقة الاستيعابية وعدم وضوح عدد المقبولين.','إعداد القوائم ونقل البيانات يدوياً.','صعوبة فرز المرشحين حسب البرنامج.','غياب قائمة انتظار منظمة وضعف المؤشرات الإدارية.']),
('15. التوصيات المستقبلية',['إشعارات القبول والرفض بالبريد أو الرسائل النصية.','إصدار شهادات إلكترونية وتسجيل الحضور والغياب.','تقييم البرامج والمدربين وإدارة قائمة الانتظار آلياً.','تقارير مقارنة ورسوم بيانية وسجل تدقيق للعمليات.','تصدير PDF ورمز QR للشهادات.','الربط بأنظمة الموارد البشرية بعد الموافقة الرسمية.','أرشفة البرامج ولوحة مؤشرات للإدارة العليا.']),
('16. النتائج المتوقعة',['رفع كفاءة إدارة البرامج وتقليل زمن معالجة الترشيحات.','تحسين جودة البيانات ومنع تجاوز المقاعد.','تسهيل إعداد التقارير والتخطيط المستقبلي.','تعزيز التحول الرقمي وتوفير معلومات دقيقة للإدارة العليا.']),
('17. الخاتمة',['يمثل نظام إدارة البرامج التدريبية للمجلس الأعلى للقضاء خطوة مهمة نحو أتمتة أعمال دائرة التدريب والتأهيل. ويوفر بيئة موحدة لإدارة البرامج والدفعات والترشيحات والمقاعد والتقارير ويقلل الاعتماد على الإجراءات اليدوية.','ينظم النظام دورة العمل من عرض البرنامج واستقبال الترشيحات إلى البحث والفرز والقبول والرفض واستخراج التقارير، مما يرفع كفاءة العمل ويحسن جودة الخدمات التدريبية.'])]

for heading, content in sections:
 h1(heading)
 if heading.startswith(('3.','4.','5.','6.','7.','8.','9.','11.','12.','13.','14.','15.','16.')): items(content)
 else:
  for x in content: para(x)

for section in doc.sections:
 p=rtl(section.footer.paragraphs[0],True)
 p.add_run('جميع الحقوق محفوظة للمجلس الأعلى للقضاء © 2026 | دائرة التدريب والتأهيل | صفحة ')
 fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); p._p.append(fld)
for p in doc.paragraphs: rtl(p,p.alignment==WD_ALIGN_PARAGRAPH.CENTER)
doc.core_properties.title='تقرير نظام إدارة البرامج التدريبية للمجلس الأعلى للقضاء'
doc.core_properties.author='دائرة التدريب والتأهيل'
doc.save(OUT)
